// Current delivery status of the message. One of:
//
// - `accepted` — the message was accepted by the platform for sending.
// - `pending` — the message is queued and awaiting a carrier response.
// - `sent` — the message was handed to the carrier.
// - `delivered` — the carrier confirmed delivery to the handset.
// - `undelivered` — the carrier reported that delivery failed.
// - `expired` — the validity period elapsed before the message was sent.
// - `rejected` — the message was rejected before sending.
// - `dlr_expired` — no delivery receipt arrived from the carrier within the expected window.
type MessageDeliveryStatus string

const (
	MessageDeliveryStatusAccepted    MessageDeliveryStatus = "accepted"
	MessageDeliveryStatusPending     MessageDeliveryStatus = "pending"
	MessageDeliveryStatusSent        MessageDeliveryStatus = "sent"
	MessageDeliveryStatusDelivered   MessageDeliveryStatus = "delivered"
	MessageDeliveryStatusUndelivered MessageDeliveryStatus = "undelivered"
	MessageDeliveryStatusExpired     MessageDeliveryStatus = "expired"
	MessageDeliveryStatusRejected    MessageDeliveryStatus = "rejected"
	MessageDeliveryStatusDlrExpired  MessageDeliveryStatus = "dlr_expired"
)

func NewMessageDeliveryStatusFromString(s string) (MessageDeliveryStatus, error) {
	switch s {
	case "accepted":
		return MessageDeliveryStatusAccepted, nil
	case "pending":
		return MessageDeliveryStatusPending, nil
	case "sent":
		return MessageDeliveryStatusSent, nil
	case "delivered":
		return MessageDeliveryStatusDelivered, nil
	case "undelivered":
		return MessageDeliveryStatusUndelivered, nil
	case "expired":
		return MessageDeliveryStatusExpired, nil
	case "rejected":
		return MessageDeliveryStatusRejected, nil
	case "dlr_expired":
		return MessageDeliveryStatusDlrExpired, nil
	}
	var t MessageDeliveryStatus
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (m MessageDeliveryStatus) Ptr() *MessageDeliveryStatus {
	return &m
}

